def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    indent_str = '  ' * indent
    result = f"{indent_str}<{self.__class__.__name__}>\n"
    for key, value in self.__dict__.items():
        if isinstance(value, list):
            result += f"{indent_str}  {key}:\n"
            for item in value:
                if hasattr(item, 'pretty'):
                    result += item.pretty(indent + 2, debug) + "\n"
                else:
                    result += f"{indent_str}    {item}\n"
        elif hasattr(value, 'pretty'):
            result += f"{indent_str}  {key}:\n"
            result += value.pretty(indent + 2, debug) + "\n"
        else:
            result += f"{indent_str}  {key}: {value}\n"
    return result.strip()

def absorb(self, args):
    result = []
    for expr in args:
        if isinstance(expr, tuple) and len(expr) == 3:
            op, left, right = expr
            if op == '&':
                if right == (('|', left, '_')):  # A & (A | B) = A
                    result.append(left)
                elif right == (('|', ('~', left), '_')):  # A & (~A | B) = A & B
                    result.append(('&', left, right[2]))
            elif op == '|':
                if right == (('&', left, '_')):  # A | (A & B) = A
                    result.append(left)
                elif right == (('&', ('~', left), '_')):  # A | (~A & B) = A | B
                    result.append(('|', left, right[2]))
            else:
                result.append(expr)
        else:
            result.append(expr)
    return result

