def deep_merge_nodes(nodes):
    from collections import defaultdict

    def merge_values(key, value, merged):
        if key in merged:
            if isinstance(value, ruamel.yaml.nodes.MappingNode) and isinstance(merged[key], ruamel.yaml.nodes.MappingNode):
                merged_value = defaultdict(list)
                for k, v in merged[key].value + value.value:
                    merged_value[k].append(v)
                merged[key].value = [merge_values(k, v[-1], merged_value) for k, v in merged_value.items()]
            else:
                merged[key] = value
        else:
            merged[key] = value
        return key, merged[key]

    merged_dict = defaultdict(list)
    for key, value in nodes:
        merged_dict[key].append(value)

    result = []
    for key, values in merged_dict.items():
        merged_value = values[0]
        for value in values[1:]:
            merged_value = merge_values(key, value, {key: merged_value})[1]
        result.append((key, merged_value))

    return result

