def deep_merge_nodes(nodes):
    from collections import defaultdict

    def merge_into(target, source):
        for key, value in source:
            if isinstance(value, ruamel.yaml.nodes.MappingNode):
                if key not in target:
                    target.append((key, ruamel.yaml.nodes.MappingNode(tag=value.tag, value=[])))
                target_value = next(v for k, v in target if k == key)
                merge_into(target_value.value, value.value)
            else:
                # Replace the value if it's not a MappingNode
                if key in (k for k, _ in target):
                    for i, (k, _) in enumerate(target):
                        if k == key:
                            target[i] = (key, value)
                            break
                else:
                    target.append((key, value))

    merged_dict = defaultdict(list)
    for key, value in nodes:
        merge_into(merged_dict[key], [(key, value)])

    return [(key, ruamel.yaml.nodes.MappingNode(tag='tag:yaml.org,2002:map', value=value)) for key, value in merged_dict.items()]

