        scale_factor = other / self._scale
        self.bins = [bin * scale_factor for bin in self.bins]
        self._scale = other

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    if make_value is None:
        make_value = lambda bin_: bin_

    graph_points = []
    for bin_ in hist.bins:
        if get_coordinate == "left":
            x = bin_.left_edge
        elif get_coordinate == "right":
            x = bin_.right_edge
        elif get_coordinate == "middle":
            x = (bin_.left_edge + bin_.right_edge) / 2
        else:
            raise ValueError("get_coordinate must be 'left', 'right', or 'middle'")

        y_values = make_value(bin_.content)
        if not isinstance(y_values, tuple):
            y_values = (y_values,)

        point = {field_names[i]: value for i, value in enumerate((x,) + y_values)}
        graph_points.append(point)

    graph_scale = hist.scale if scale is True else scale
    return Graph(points=graph_points, scale=graph_scale, field_names=field_names)

def _verify(iface, candidate, tentative=False, vtype=None):
    errors = []

    if not tentative and not iface.providedBy(candidate):
        errors.append(f"Candidate does not provide the interface {iface}")

    required_methods = set(iface.names(all=True, inherited=True))
    candidate_methods = set(dir(candidate))

    missing_methods = required_methods - candidate_methods
    for method in missing_methods:
        errors.append(f"Missing method: {method}")

    for method in required_methods:
        if method in candidate_methods:
            required_signature = iface.get(method)
            candidate_method = getattr(candidate, method)
            if not _compare_signatures(required_signature, candidate_method):
                errors.append(f"Incorrect signature for method: {method}")

    required_attributes = set(attr for attr in iface.names(all=True, inherited=True) if not callable(iface[attr]))
    candidate_attributes = set(attr for attr in dir(candidate) if not callable(getattr(candidate, attr)))

    missing_attributes = required_attributes - candidate_attributes
    for attr in missing_attributes:
        errors.append(f"Missing attribute: {attr}")

    if errors:
        if len(errors) == 1:
            raise zope.interface.Invalid(errors[0])
        else:
            raise zope.interface.Invalid("\n".join(errors))

    return True

