def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    import re
    tags = set()
    code_block = False
    lines = text.split('\n')
    result_lines = []

    for line in lines:
        if line.strip().startswith('```'):
            code_block = not code_block
        if not code_block:
            tag_matches = re.findall(r'#(\w+)', line)
            for tag in tag_matches:
                tags.add(tag)
                if replacer:
                    line = re.sub(rf'#\b{tag}\b', replacer(tag), line)
        result_lines.append(line)

    return tags, '\n'.join(result_lines)

